mapper.select:
SELECT COALESCE(SUM(t.amount), 0) FROM (
    SELECT e.debit - e.credit AS amount
    FROM fin_voucher_entry e
    JOIN fin_voucher v ON v.id = e.voucher_id
    WHERE v.voucher_date < #{date} 
      AND e.account_id IN #{id}
    UNION ALL
    SELECT o.debit - o.credit FROM fin_account_opening o
    WHERE o.account_id IN #{id}
) t

SELECT DISTINCT e.voucher_id AS "voucherId", a.name AS "accountName"
FROM fin_voucher_entry e
JOIN fin_account a ON a.id = e.account_id
WHERE e.voucher_id IN #{id}
  AND e.account_id NOT IN #{id}

SELECT t.account_id AS "accountId", SUM(t.amount) AS "balance" FROM (
    SELECT e.account_id, e.debit - e.credit AS amount
    FROM fin_voucher_entry e
    JOIN fin_voucher v ON v.id = e.voucher_id
    WHERE v.voucher_date < #{date} 
      AND e.account_id IN #{id}
    UNION ALL
    SELECT o.account_id, o.debit - o.credit FROM fin_account_opening o
    WHERE o.account_id IN #{id}
) t
GROUP BY t.account_id
